import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import HeaderList from 'flarum/forum/components/HeaderList';
import DialogList from './DialogList';
import LinkButton from 'flarum/common/components/LinkButton';
import ItemList from 'flarum/common/utils/ItemList';
import Tooltip from 'flarum/common/components/Tooltip';
import Button from 'flarum/common/components/Button';
export default class DialogDropdownList extends Component {
  oninit(vnode) {
    super.oninit(vnode);
  }
  view() {
    const state = this.attrs.state;
    return m(HeaderList, {
      className: "DialogDropdownList",
      title: app.translator.trans('flarum-messages.forum.dialog_list.title'),
      controls: this.controlItems(),
      hasItems: state.hasItems(),
      loading: state.isInitialLoading(),
      emptyText: app.translator.trans('flarum-messages.forum.messages_page.empty_text'),
      loadMore: () => state.hasNext() && !state.isLoadingNext() && state.loadNext(),
      footer: () => m("h4", null, m(LinkButton, {
        href: app.route('messages'),
        className: "Button Button--link",
        icon: "fas fa-inbox"
      }, app.translator.trans('flarum-messages.forum.dialog_list.view_all')))
    }, m("div", {
      className: "HeaderListGroup-content"
    }, this.content()));
  }
  controlItems() {
    const items = new ItemList();
    const state = this.attrs.state;
    if (app.session.user.attribute('unreadDialogCount') > 0) {
      items.add('mark_all_as_read', m(Tooltip, {
        text: app.translator.trans('flarum-messages.forum.messages_page.mark_all_as_read_tooltip')
      }, m(Button, {
        className: "Button Button--link",
        "data-container": ".DialogDropdownList",
        icon: "fas fa-check",
        title: app.translator.trans('flarum-messages.forum.messages_page.mark_all_as_read_tooltip'),
        onclick: state.markAllAsRead.bind(state)
      })), 70);
    }
    return items;
  }
  content() {
    return m(DialogList, {
      state: this.attrs.state,
      hideMore: true,
      itemActions: true
    });
  }
}
flarum.reg.add('flarum-messages', 'forum/components/DialogDropdownList', DialogDropdownList);